99	func TestSnapshotRoundTrip(t *testing.T) {
100		snap := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["A","B"]}]}`)
101		data, err := MarshalSnapshot(snap)
