1	// Package chainledger graph structure rules shared by every graph reader.
2	//
3	// Both on-disk graph files (UnmarshalGraphFile) and the graph embedded in a
4	// snapshot (ParseSnapshot) describe the same thing: a set of dataset names and
5	// each dataset's direct upstreams. The rules below are the single authority for
6	// turning that description into the validated, normalized adjacency both
7	// readers build on, so the two file formats can never disagree about whether
8	// one graph is legal or about which lineage relations it expresses:
9	//
10	//   - an empty dataset name is rejected;
11	//   - a dataset declared more than once is rejected;
12	//   - an upstream that is not itself a declared dataset is rejected, with the
13	//     referrer and the referenced name both in the error;
14	//   - a direct self-dependency or any indirect dependency cycle is rejected,
15	//     with the datasets on the cycle named;
16	//   - names are case-sensitive and surrounding whitespace is kept verbatim;
17	//   - record order and upstream order are irrelevant, duplicate upstreams count
18	//     as one relationship, and an empty upstream list marks a root, so an
19	//     empty graph stays legal;
20	//   - a known field declared twice within the same object (datasets in the
21	//     graph object, name or upstreams in a dataset record) is rejected, however
22	//     the two declarations are spelled.
23	//
24	// The snapshot-only envelope rules (required fields, format version, content
25	// identifier, and duplicates of the snapshot's own fields) live in
26	// snapshot.go; this file is only the common graph structure.
27	package chainledger
28	
29	import (
30		"fmt"
31		"sort"
32		"strings"
33	)
34	
35	// adjacency maps a dataset name to its sorted, duplicate-free parent names.
36	type adjacency map[string][]string
37	
38	// normalizeDatasets builds the normalized parent adjacency from parsed dataset
39	// records. It rejects empty dataset names and datasets declared more than
40	// once; every surviving upstream list is sorted and deduplicated. It does not
41	// check that upstreams resolve to a declared dataset; use
42	// validateAdjacencyReferences for that.
43	func normalizeDatasets(datasets []GraphDataset) (adjacency, error) {
44		adj := make(adjacency, len(datasets))
45		for _, ds := range datasets {
46			if ds.Name == "" {
47				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
48			}
49			if _, exists := adj[ds.Name]; exists {
50				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
51			}
52			adj[ds.Name] = uniqueSorted(ds.Upstreams)
53		}
54		return adj, nil
55	}
56	
57	// validateAdjacencyReferences rejects an edge whose upstream is not a declared
58	// dataset. Referrers are visited in sorted order with their parents sorted, so
59	// the first reported (referrer, upstream) pair is stable regardless of map
60	// iteration or record order.
61	func validateAdjacencyReferences(adj adjacency) error {
62		names := make([]string, 0, len(adj))
63		for name := range adj {
64			names = append(names, name)
65		}
66		sort.Strings(names)
67		for _, name := range names {
68			for _, parent := range adj[name] {
69				if _, ok := adj[parent]; !ok {
70					return fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
71				}
72			}
73		}
74		return nil
75	}
76	
77	// validateGraphStructureFromFile runs every graph-structure rule shared by the
78	// file readers: it normalizes the records, rejects empty names, duplicate
79	// datasets, and unregistered upstreams, then rejects cycles. The returned
80	// adjacency is the canonical form of the graph's semantics.
81	func validateGraphStructureFromFile(datasets []GraphDataset) (adjacency, error) {
82		adj, err := normalizeDatasets(datasets)
83		if err != nil {
84			return nil, err
85		}
86		if err := validateAdjacencyReferences(adj); err != nil {
87			return nil, err
88		}
89		if err := validateAcyclic(adj); err != nil {
90			return nil, err
91		}
92		return adj, nil
93	}
94	
95	// validateAcyclic reports an error if the parent adjacency contains a cycle
96	// (including a dataset that depends on itself). The error message names the
97	// datasets involved.
98	func validateAcyclic(adj adjacency) error {
99		const (
100			white = 0
101			gray  = 1
102			black = 2
103		)
104		color := make(map[string]int, len(adj))
105		var stack []string
106	
107		var dfs func(node string) error
108		dfs = func(node string) error {
109			color[node] = gray
110			stack = append(stack, node)
111			for _, parent := range adj[node] {
112				switch color[parent] {
113				case gray:
114					// parent is an ancestor of node in the current DFS path, so
115					// following parent edges from parent leads back to parent.
116					idx := 0
117					for stack[idx] != parent {
118						idx++
119					}
120					cycle := make([]string, 0, len(stack)-idx+1)
121					cycle = append(cycle, stack[idx:]...)
122					cycle = append(cycle, parent)
123					return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
124				case white:
125					if err := dfs(parent); err != nil {
126						return err
127					}
128				}
129			}
130			color[node] = black
131			stack = stack[:len(stack)-1]
132			return nil
133		}
134	
135		// Iterate over a sorted snapshot so the first reported cycle is stable
136		// across runs regardless of map iteration order.
137		names := make([]string, 0, len(adj))
138		for name := range adj {
139			names = append(names, name)
140		}
141		sort.Strings(names)
142		for _, name := range names {
143			if color[name] == white {
144				if err := dfs(name); err != nil {
145					return err
146				}
147			}
148		}
149		return nil
150	}
151	
152	// lineageFromAdjacency rebuilds the in-memory graph from validated, normalized
153	// parent adjacency: children are derived from the parent edges, so every
154	// parent/child pair corresponds and both lists stay sorted and duplicate-free.
155	// The result is independent of the caller's record slices.
156	func lineageFromAdjacency(adj adjacency) map[string]*Lineage {
157		graph := make(map[string]*Lineage, len(adj))
158		for name, parents := range adj {
159			graph[name] = &Lineage{
160				Dataset: name,
161				Parents: append([]string(nil), parents...),
162			}
163		}
164		for name, parents := range adj {
165			for _, parent := range parents {
166				graph[parent].Children = append(graph[parent].Children, name)
167			}
168		}
169		for name := range graph {
170			graph[name].Children = uniqueSorted(graph[name].Children)
171		}
172		return graph
173	}
174

